def run(*args: str) -> str:
    cp = subprocess.run(
        args,
        cwd=ROOT,
        text=True,
        encoding="utf-8",
        errors="replace",
        capture_output=True,
    )
    if cp.returncode != 0:
        raise RuntimeError(
            cp.stderr.strip()
            or cp.stdout.strip()
            or f"command failed: {args}"
        )
    return cp.stdout.strip()


def replace_exact(text: str, old: str, new: str, label: str) -> str:
    count = text.count(old)
    if count != 1:
        raise RuntimeError(
            f"Anchor mismatch for {label}: expected 1, got {count}"
        )
    return text.replace(old, new, 1)


def _load_stage6h2a():
    if not STAGE6H2A_HELPER.is_file():
        raise RuntimeError(
            "Stage 6H.2A guarded patch helper is required to reconstruct "
            "the exact accepted local baseline."
        )
    spec = importlib.util.spec_from_file_location(
        "stage6h2a_baseline_helper",
        STAGE6H2A_HELPER,
    )
    if spec is None or spec.loader is None:
        raise RuntimeError("Could not load Stage 6H.2A helper.")
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


def _git_show(rel: str) -> str:
    return run("git", "show", f"HEAD:{rel}")


def validate_stage6h2a_baseline() -> tuple[dict[str, str], set[str]]:
    if run("git", "rev-parse", "HEAD") != EXPECTED_HEAD:
        raise RuntimeError("HEAD moved; refusing Stage 6H.2B.1 patch.")
    if run("git", "rev-parse", "origin/main") != EXPECTED_HEAD:
        raise RuntimeError("origin/main moved; refusing Stage 6H.2B.1 patch.")

    helper = _load_stage6h2a()
    if helper.EXPECTED_HEAD != EXPECTED_HEAD:
        raise RuntimeError("Stage 6H.2A helper baseline mismatch.")

    baseline = {
        rel: _git_show(rel)
        for rel in helper.EXPECTED_BLOBS
    }
    expected_rendered = helper.render(baseline)
    helper.validate_rendered(expected_rendered)

    expected_changed = (
        set(helper.FULL_REPLACEMENTS)
        | set(helper.REPLACE_OPS)
        | set(helper.BETWEEN_OPS)
        | set(helper.NEW_FILES)
    )

    status = run("git", "status", "--porcelain", "--untracked-files=all")
    production_changed = set()
    staged_production = []
    for line in status.splitlines():
        if not line:
            continue
        code = line[:2]
        rel = line[3:].strip().replace("\\", "/")
        if rel.startswith("wa_backend/"):
            production_changed.add(rel)
            if code[0] != " " and code[0] != "?":
                staged_production.append(line)

    if staged_production:
        raise RuntimeError(
            "Production changes are staged before Stage 6H.2B.1 acceptance:\n"
            + "\n".join(staged_production)
        )

    # Stage 6H.2A was already independently accepted.  If a tracked file later
    # returned *exactly* to the committed HEAD baseline, that is a deterministic
    # revert, not an unknown drift.  Only api/offers.py is approved for surgical
    # restoration here because it is the sole missing file reported after the
    # accepted 79/79 gate.  Anything else still fails closed.
    restorable: set[str] = set()
    approved_restore = {"wa_backend/api/offers.py"}

    for rel in sorted(expected_changed):
        path = ROOT / rel
        if rel in helper.NEW_FILES:
            expected_text = helper.NEW_FILES[rel]
            if not path.is_file() or path.read_text(encoding="utf-8") != expected_text:
                raise RuntimeError(
                    f"Accepted Stage 6H.2A new file drifted: {rel}"
                )
            continue

        expected_text = expected_rendered[rel]
        actual = path.read_text(encoding="utf-8")
        if actual == expected_text:
            continue

        head_text = baseline.get(rel)
        if rel in approved_restore and head_text is not None and actual == head_text:
            restorable.add(rel)
            continue

        raise RuntimeError(
            f"Accepted Stage 6H.2A file drifted unexpectedly: {rel}"
        )

    expected_actual_surface = expected_changed - restorable
    if production_changed != expected_actual_surface:
        missing = sorted(expected_actual_surface - production_changed)
        unexpected = sorted(production_changed - expected_actual_surface)
        raise RuntimeError(
            "Stage 6H.2A production surface mismatch after content validation. "
            f"missing={missing} unexpected={unexpected}"
        )

    for rel, expected_sha in BASELINE_UNTOUCHED.items():
        actual_sha = run("git", "hash-object", rel)
        if actual_sha != expected_sha:
            raise RuntimeError(
                f"Untouched baseline drift for {rel}: "
                f"expected={expected_sha} actual={actual_sha}"
            )

    for rel in NEW_FILES:
        if (ROOT / rel).exists():
            raise RuntimeError(
                f"Refusing to overwrite existing Stage 6H.2B.1 file: {rel}"
            )

    return expected_rendered, restorable


def render() -> dict[str, str]:
    targets = set(FULL_REPLACEMENTS) | set(REPLACE_OPS)
    rendered = {
        rel: (ROOT / rel).read_text(encoding="utf-8")
        for rel in targets
    }
    rendered.update(FULL_REPLACEMENTS)

    for rel, operations in REPLACE_OPS.items():
        text = rendered[rel]
        for old, new, label in operations:
            text = replace_exact(text, old, new, label)
        rendered[rel] = text

    all_files = dict(rendered)
    all_files.update(NEW_FILES)
    for rel, text in all_files.items():
        if rel.endswith(".py"):
            compile(text, rel, "exec")

    # Hard semantic guards: no single-price authority in the new calculation/evidence path.
    calc_contracts = rendered[
        "wa_backend/domains/sales_calculation/contracts.py"
    ]
    calc_service = rendered[
        "wa_backend/domains/sales_calculation/service.py"
    ]
    calc_pipeline = rendered[
        "wa_backend/domains/sales_calculation/pipeline.py"
    ]
    evidence_models = rendered[
        "wa_backend/domains/sales_evidence/models.py"
    ]
    evidence_service = rendered[
        "wa_backend/domains/sales_evidence/service.py"
    ]
    migration = next(iter(NEW_FILES.values()))

    required = [
        (
            "class CalculationInputComponent" in calc_contracts
            and "price_components: tuple[CalculatedPriceComponent, ...]" in calc_contracts,
            "mixed-UOM calculation contracts",
        ),
        (
            "load_variant_uom_authorities" in calc_service
            and "pairs=sorted(requested_pairs)" in calc_service,
            "bulk mixed-UOM price resolution",
        ),
        (
            "CalculatedPriceComponent(" in calc_pipeline
            and "line.price_components" in calc_pipeline,
            "component-level calculation pipeline",
        ),
        (
            "class SalesLinePriceComponent" in evidence_models
            and "uom_id = Column(Integer, nullable=False)" in evidence_models,
            "typed immutable price evidence model",
        ),
        (
            "SalesLinePriceComponent(" in evidence_service
            and "item.selected_price_entry_id = None" in evidence_service,
            "single-price parent authority removed",
        ),
        (
            "sales_line_price_components" in migration
            and "price_base_total <> NEW.canonical_quantity" in migration
            and "price_gross_total <> NEW.gross_amount" in migration,
            "DB price evidence reconciliation",
        ),
    ]
    failed = [label for ok, label in required if not ok]
    if failed:
        raise RuntimeError(
            "Rendered Stage 6H.2B.1 semantic guard failed: "
            + ", ".join(failed)
        )
    return rendered


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()

    expected_h2a, restorable = validate_stage6h2a_baseline()
    rendered = render()
    print("STAGE6H2B1_PATCH_CHECK=PASS")
    print("BASELINE=STAGE6H2A_ACCEPTED")
    print(
        "SAFE_RESTORE="
        + (",".join(sorted(restorable)) if restorable else "NONE")
    )
    print("PRICE_AUTHORITY=SALES_LINE_PRICE_COMPONENTS")
    print("LIVE_DRIVER_CUTOVER=NO")
    if args.check:
        return 0

    # Restore only an exact committed-baseline revert to its independently
    # accepted Stage 6H.2A content. No fuzzy merge and no unknown drift.
    for rel in sorted(restorable):
        (ROOT / rel).write_text(
            expected_h2a[rel],
            encoding="utf-8",
            newline="\n",
        )

    for rel, text in rendered.items():
        (ROOT / rel).write_text(
            text,
            encoding="utf-8",
            newline="\n",
        )
    for rel, text in NEW_FILES.items():
        path = ROOT / rel
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(
            text,
            encoding="utf-8",
            newline="\n",
        )

    run("git", "diff", "--check")
    print("STAGE6H2B1_PATCH_APPLIED=PASS")
    print("NEXT=RUN_STAGE6H2B1_GATE")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
